    "mail.upgrade.bodyIntroIndia": "இந்திய வாழ்நாள் பாஸ் மூலம் வரம்பற்ற வகுப்புகளையும் ஏற்றுமதிகளையும் திறக்க உங்கள் நேரடி ஒரே-கிளிக் இணைப்பு இதோ. தொடர் தானியங்கு பற்று இல்லை, சந்தாக் கட்டணம் இல்லை — UPI அல்லது கார்டு மூலம் ஒருமுறை செலுத்தி என்றென்றும் உரிமையாக்குங்கள்:",
