    "mail.upcoming.now.subject": "நினைவூட்டல்: \"{title}\" தொடங்குகிறது",
    "mail.upcoming.now.body": "உங்கள் தொடர் கூட்டம் \"{title}\" இப்போது தொடங்குகிறது. நீங்கள் சேர்ந்ததும், Attendance Tracker பக்கப் பலகத்தைத் திறந்தால் யார் இருக்கிறார்கள் என்பதைப் பதிவு செய்யும் — பின்னர் ஒரே கிளிக்கில் அறிக்கையை ஏற்றுமதி செய்யுங்கள் (அல்லது கூட்டம் முடிந்ததும் தானாக ஏற்றுமதி ஆகட்டும்).\n\nஇந்தக் கூட்டத்தை முன்பு கண்காணித்தீர்கள், ஆனால் கடந்த சில நாட்களாக இல்லை — தவறவிடாமல் இருக்க ஒரு சிறிய நினைவூட்டல்.\n\n— Derek",
