    "mail.review.bullets": "Google Meet‌లో అపరిమిత ఆటోమేటిక్ ట్రాకింగ్ & ఖచ్చితమైన చేరిక/నిష్క్రమణ సమయాలు.\nమీ Drive‌లోని Google Sheets‌కు నేరుగా ఎగుమతి.\nక్రెడిట్ కార్డ్ అవసరం లేదు & $0 ఖర్చు — ఊహించని ఛార్జీలు లేవు.",
    "mail.review.closing": "ఇది మీ తరగతుల్లో సమయాన్ని ఆదా చేస్తుందని ఆశిస్తున్నాం. ఏవైనా ప్రశ్నలు లేదా సూచనలు ఉంటే, ఈ ఇమెయిల్‌కు నేరుగా ప్రత్యుత్తరం ఇవ్వండి!",
