    "mail.upcoming.now.subject": "రిమైండర్: \"{title}\" ప్రారంభమవుతోంది",
    "mail.upcoming.now.body": "మీ పునరావృత సమావేశం \"{title}\" ఇప్పుడే ప్రారంభమవుతోంది. మీరు చేరినప్పుడు, Attendance Tracker సైడ్ ప్యానెల్ తెరవండి — అది ఎవరు ఉన్నారో నమోదు చేస్తుంది — ఆపై ఒక్క క్లిక్‌లో నివేదికను ఎగుమతి చేయండి (లేదా సమావేశం ముగిసినప్పుడు ఆటోమేటిక్‌గా ఎగుమతి అవ్వనివ్వండి).\n\nమీరు ఈ సమావేశాన్ని ఇంతకు ముందు ట్రాక్ చేశారు కానీ గత కొన్ని రోజులుగా చేయలేదు కాబట్టి ఇది మీకు వస్తోంది — మిస్ కాకుండా ఉండేందుకు ఒక చిన్న గుర్తుచేత.\n\n— Derek",
    "mail.upcoming.now.badge": "⏰ ఇప్పుడే ప్రారంభం",
    "mail.upcoming.soon.subject": "రిమైండర్: \"{title}\" త్వరలో ప్రారంభమవుతుంది",
