    "mail.review.title": "የPro መዳረሻ ተከፍቷል!",
    "mail.review.p1": "Attendance Trackerን በGoogle Workspace Marketplace ላይ ስለገመገሙ ከልብ እናመሰግናለን! ለመምህራን የተሰራ ገለልተኛ መሣሪያ እንደመሆኑ፣ የእርስዎ አስተያየትና ድጋፍ ትልቅ ለውጥ ያመጣል።",
    "mail.review.cardTitle": "🎉 የ1 ወር Educator Pro ገቢር ሆኗል",
