    "mail.review.bullets": "ያልተገደበ ራስ-ሰር ክትትል እና በGoogle Meet ውስጥ ትክክለኛ የመግቢያ/የመውጫ ሰዓቶች።\nበDriveዎ ውስጥ ወደ Google Sheets በቀጥታ መላክ።\nክሬዲት ካርድ አያስፈልግም፣ ወጪው $0 ነው — ምንም ያልተጠበቀ ክፍያ የለም።",
