    "mail.review.p1": "Google Workspace Marketplace හි Attendance Tracker ශ්‍රේණිගත කළාට ඔබට බොහොම ස්තූතියි! ගුරුවරුන් සඳහා සාදන ලද ස්වාධීන මෙවලමක් ලෙස, ඔබගේ ප්‍රතිචාර සහ සහාය විශාල වෙනසක් ඇති කරයි.",
