    "mail.upgrade.bodyIntroIndia": "India Lifetime Pass සමඟ අසීමිත පන්ති සහ අපනයන විවෘත කිරීමට ඔබගේ සෘජු එක්-ක්ලික් සබැඳිය මෙන්න. පුනරාවර්තන ස්වයංක්‍රීය අයකිරීම් නැත, දායක ගාස්තු නැත — UPI හෝ කාඩ්පත හරහා එක් වරක් ගෙවා සදහටම හිමි කරගන්න:",
