    "mail.upcoming.now.subject": "මතක් කිරීම: \"{title}\" ආරම්භ වෙමින් පවතී",
    "mail.upcoming.now.body": "ඔබගේ පුනරාවර්තන රැස්වීම \"{title}\" දැන් ආරම්භ වෙමින් පවතී. ඔබ සම්බන්ධ වූ විට, Attendance Tracker පැති පැනලය විවෘත කරන්න, එය පැමිණ සිටින අය වාර්තා කරයි — ඉන්පසු එක් ක්ලික් කිරීමකින් වාර්තාව අපනයනය කරන්න (නැතහොත් රැස්වීම අවසන් වූ විට ස්වයංක්‍රීයව අපනයනය වීමට ඉඩ දෙන්න).\n\nඔබ මීට පෙර මෙම රැස්වීම ලුහුබැඳ ඇති නමුත් පසුගිය දින කිහිපය තුළ නොකළ නිසා ඔබට මෙය ලැබේ — එය මග නොහැරීමට කුඩා මතක් කිරීමක් පමණි.\n\n— Derek",
    "mail.upcoming.now.badge": "⏰ දැන් ආරම්භ වේ",
    "mail.upcoming.soon.subject": "මතක් කිරීම: \"{title}\" ඉක්මනින් ආරම්භ වේ",
    "mail.upcoming.soon.body": "ඔබගේ පුනරාවර්තන රැස්වීම \"{title}\" මිනිත්තු {minutes}කින් පමණ ආරම්භ වේ. ඔබ සම්බන්ධ වූ විට, Attendance Tracker පැති පැනලය විවෘත කරන්න, එය පැමිණ සිටින අය වාර්තා කරයි — ඉන්පසු එක් ක්ලික් කිරීමකින් වාර්තාව අපනයනය කරන්න (නැතහොත් රැස්වීම අවසන් වූ විට ස්වයංක්‍රීයව අපනයනය වීමට ඉඩ දෙන්න).\n\nඔබ මීට පෙර මෙම රැස්වීම ලුහුබැඳ ඇති නමුත් පසුගිය දින කිහිපය තුළ නොකළ නිසා ඔබට මෙය ලැබේ — එය මග නොහැරීමට කුඩා මතක් කිරීමක් පමණි.\n\n— Derek",
    "mail.upcoming.soon.badge": "⏰ ඉක්මනින් ආරම්භ වේ"
