    "mail.upcoming.now.body": "ನಿಮ್ಮ ಮರುಕಳಿಸುವ ಸಭೆ \"{title}\" ಈಗ ಪ್ರಾರಂಭವಾಗುತ್ತಿದೆ. ನೀವು ಸೇರಿದಾಗ Attendance Tracker ಸೈಡ್ ಪ್ಯಾನೆಲ್ ತೆರೆಯಿರಿ, ಯಾರು ಇದ್ದಾರೆ ಎಂಬುದನ್ನು ಅದು ದಾಖಲಿಸುತ್ತದೆ — ನಂತರ ಒಂದೇ ಕ್ಲಿಕ್‌ನಲ್ಲಿ ವರದಿಯನ್ನು ರಫ್ತು ಮಾಡಿ (ಅಥವಾ ಸಭೆ ಮುಗಿದಾಗ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ರಫ್ತಾಗಲು ಬಿಡಿ).\n\nನೀವು ಈ ಸಭೆಯನ್ನು ಹಿಂದೆ ಟ್ರ್ಯಾಕ್ ಮಾಡಿದ್ದೀರಿ ಆದರೆ ಕಳೆದ ಕೆಲವು ದಿನಗಳಲ್ಲಿ ಮಾಡಿಲ್ಲವಾದ್ದರಿಂದ ಇದನ್ನು ಪಡೆಯುತ್ತಿದ್ದೀರಿ — ಅದು ತಪ್ಪಿಹೋಗದಂತೆ ಒಂದು ಸಣ್ಣ ಜ್ಞಾಪನೆ ಅಷ್ಟೇ.\n\n— Derek",
