    "mail.review.p1": "Google Workspace Marketplace တွင် Attendance Tracker ကို အဆင့်သတ်မှတ်ပေးသည့်အတွက် အထူးကျေးဇူးတင်ပါသည်! ဆရာ၊ ဆရာမများအတွက် တည်ဆောက်ထားသော လွတ်လပ်သည့် ကိရိယာတစ်ခုအနေဖြင့် သင်၏ အကြံပြုချက်နှင့် ပံ့ပိုးမှုသည် အလွန်အရေးပါပါသည်။",
