    "mail.review.bullets": "Google Meet တွင် အကန့်အသတ်မဲ့ အလိုအလျောက် ခြေရာခံခြင်းနှင့် တိကျသော ဝင်/ထွက် အချိန်များ။\nသင်၏ Drive ရှိ Google Sheets သို့ တိုက်ရိုက် ထုတ်ယူခြင်း။\nခရက်ဒစ်ကတ် မလိုအပ်ပါ၊ ကုန်ကျစရိတ် $0 — မမျှော်လင့်သော ကောက်ခံမှု လုံးဝမရှိပါ။",
    "mail.review.closing": "၎င်းက သင့်အတန်းများတွင် အချိန်ကုန်သက်သာစေမည်ဟု မျှော်လင့်ပါသည်။ မေးခွန်း သို့မဟုတ် အကြံပြုချက်ရှိပါက ဤအီးမေးလ်ကို တိုက်ရိုက် ပြန်ကြားနိုင်ပါသည်!",
